text:
{
  "justification": "Unprompted salience clusters around healthcare, the economy/inflation, immigration, housing and education, so I weight foundations by how strongly these issues typically invoke each moral lens, while noting many issues touch multiple foundations. As the survey has no directional information, the weights capture likelihood of activation (in either direction), not policy stance.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Ageing population/Social care; Mental health/Well-being; Housing; Education/Schools; Crime/Law and order (harm/safety); Pollution/Environment/Climate change; Coronavirus/Pandemic diseases",
      "weight": 0.29
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Pensions/Social security/Benefits; Housing; Education/Schools; Race relations; Public services in general; Taxation (redistribution)",
      "weight": 0.18
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Inflation/Prices; Taxation; Unemployment/Factory closure/Lack of industry; Low pay/Fair wages; Public services in general (value for money); Nationalisation/Privatisation",
      "weight": 0.18
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration/Immigrants; Defence/Foreign affairs/International terrorism; Common Market/Brexit/EU/Europe; UK union/Devolution/Reform; Nuclear weapons/Disarmament; Population levels/Overpopulation; Race relations",
      "weight": 0.17
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Lack of faith in politics/politicians/government; Local government/Council tax; Northern Ireland; Education/Schools (discipline/norms)",
      "weight": 0.10
    },
    {
      "foundation": "sanctity",
      "basis": "Pollution/Environment/Climate change; Morality/Individual behaviour/Lifestyle; Drug abuse; Food production/Farming; Coronavirus/Pandemic diseases; Population levels/Overpopulation (naturalness/contamination)",
      "weight": 0.08
    }
  ]
}
